using UnityEngine;using UnityEditor;using System;
public static class ValidateMowerRoad {public static string Main(){var mode=Physics.simulationMode;GameObject copy=null;try{Physics.simulationMode=SimulationMode.Script;var start=new Vector3(39,0,87.9f);start.y=Terrain.activeTerrain.SampleHeight(start)+Terrain.activeTerrain.transform.position.y+.03f;copy=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/Lawnmower/Driveable/Lawnmower_With_Trailer.prefab"),start,Quaternion.LookRotation(new Vector3(1,0,.46f)));var lawn=copy.GetComponentInChildren<LawnmowerController>();var motor=lawn.GetComponent<MotorollerController>();Physics.SyncTransforms();for(int i=0;i<100;i++){lawn.UpdateHitch();Physics.Simulate(.02f);}motor.Movement.SetRidden(true);for(int i=0;i<600&&lawn.transform.position.x<60;i++){motor.Drive(1,0,false,.02f);lawn.UpdateHitch();Physics.Simulate(.02f);lawn.SendMessage("LateUpdate");}if(lawn.transform.position.x<60)throw new Exception("Road stopped at "+lawn.transform.position);float gap=Vector3.Distance(lawn.hitchTarget.position,lawn.trailerJoint.transform.TransformPoint(lawn.trailerJoint.anchor));if(gap>.25f)throw new Exception("Hitch gap "+gap);return "PASS: mower and trailer cross road incline; end="+lawn.transform.position+" hitch gap="+gap;}finally{if(copy)UnityEngine.Object.DestroyImmediate(copy);Physics.simulationMode=mode;}}}
